export function compareCosts(a,shippingA,b,shippingB){const values=[a,shippingA,b,shippingB];if(!values.every(v=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=10000000))return null;const cents=values.map(v=>Math.round((v+Number.EPSILON)*100));const first=cents[0]+cents[1],second=cents[2]+cents[3];return{a:first/100,b:second/100,difference:Math.abs(first-second)/100,winner:first===second?'equal':first<second?'a':'b'};}
if(typeof document!=='undefined')document.querySelectorAll('[data-shop-guide]').forEach(root=>{
 const source=root.querySelector('[data-shopping-config]');if(!source)return;
 const c=JSON.parse(source.textContent),money=new Intl.NumberFormat(c.locale,{style:'currency',currency:'EUR'});
 const input=[...root.querySelectorAll('[data-cost]')],result=root.querySelector('.sg-result');
 const update=()=>{const [a,sa,b,sb]=input.map(el=>el.value.trim()===''?NaN:Number(el.value));const values=compareCosts(a,sa,b,sb),error=root.querySelector('[data-calc-error]');error.hidden=!!values;root.querySelector('[data-calc-winner]').textContent=values?(values.winner==='equal'?c.labels.equal:c.labels[values.winner]):'';root.querySelector('[data-calc-difference]').textContent=values?money.format(values.difference):'';result.dataset.valid=String(!!values);error.textContent=values?'':c.labels.invalid;for(const key of ['a','b'])root.querySelector(`[data-total="${key}"]`).textContent=values?money.format(values[key]):'';input.forEach(el=>el.setAttribute('aria-invalid',String(!Number.isFinite(el.valueAsNumber)||el.valueAsNumber<0||el.valueAsNumber>10000000)));};
 input.forEach(el=>el.addEventListener('input',update));root.querySelector('form')?.addEventListener('submit',e=>e.preventDefault());update();
 const selector=root.querySelector('[data-calendar-year]');selector?.addEventListener('change',()=>{const year=Number(selector.value),record=c.calendar[year];if(!record)return;const time=root.querySelector('[data-calendar-date]');time.dateTime=record.date;time.textContent=new Intl.DateTimeFormat(c.locale,{dateStyle:'full',timeZone:'UTC'}).format(new Date(record.date+'T00:00:00Z'));root.querySelector('[data-calendar-download]').href=c.asset+c.slug+'-'+year+'.ics';root.querySelector('[data-calendar-google]').href=record.google;});
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:c.zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());root.querySelectorAll('[data-offer-end]').forEach(offer=>{if(today>offer.dataset.offerEnd){offer.classList.add('sg-offer-ended');offer.querySelector('[data-offer-status]').textContent=c.labels.ended+'. '+c.labels.review;}});
});
